'use client';
import {FinancialOpeningAction} from './financial-opening-action';
import {FinancialInvoiceApplication} from './financial-invoice-application';
import {FinancialOpeningCorrection,type CorrectionTarget} from './financial-opening-correction';
import {useRef,useEffect,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {downloadReport} from '@/lib/report-export';
import {readFinancialOpeningAccount,openingAccountReportRows} from '@/lib/financial-opening-account';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
export function FinancialOpeningAccount({scope,reservation,initialDate}:{scope:HandoffScope;reservation:string;initialDate:string}){
 const [correction,setCorrection]=useState<CorrectionTarget|null>(null),[correctionLocked,setCorrectionLocked]=useState(false),[actionLocked,setActionLocked]=useState(false),[invoiceLocked,setInvoiceLocked]=useState(false);
 const [date,setDate]=useState(initialDate),[result,setResult]=useState<ReturnType<typeof readFinancialOpeningAccount>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 async function load(){if(lock.current)return;lock.current=true;setBusy(true);setResult(null);setError('');try{const identify=async()=>{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen the account.')};await identify();const value=readFinancialOpeningAccount(await hotelRpc('financial_opening_account',{p_tenant:scope.tenant,p_property:scope.property,p_reservation:reservation,p_as_of:date}),scope,reservation,date);await identify();if(alive.current)setResult(value)}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load opening account.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section className="card"><h3>Migrated balance account</h3><p>Reservation {reservation}. These source balances are separate from the destination folio.</p><label>Balances as of<input type="date" value={date} disabled={busy||correctionLocked||actionLocked||invoiceLocked} onChange={e=>{setDate(e.target.value);setResult(null)}}/></label><button type="button" disabled={busy||correctionLocked||actionLocked||invoiceLocked||!date} onClick={()=>void load()}>Load migrated account</button>{error&&<p role="alert">{error}</p>}{result&&<><button type="button" disabled={busy||correctionLocked||actionLocked||invoiceLocked} onClick={()=>{try{downloadReport('migrated-account-'+reservation+'-'+result.date,openingAccountReportRows(result))}catch(e){setError(e instanceof Error?e.message:'Unable to export account.')}}}>Export migrated account CSV</button><p>Overdue source receivables: {bankCloseMoney(result.overdue.toString())}</p><dl>{Object.entries({current:'Current',days1to30:'1–30 days overdue',days31to60:'31–60 days overdue',days61to90:'61–90 days overdue',days91plus:'91+ days overdue'}).map(([bucket,label])=><div key={bucket}><dt>{label}</dt><dd>{bankCloseMoney(result.aging[bucket as keyof typeof result.aging].toString())}</dd></div>)}</dl>{(['receivable','prepayment','security'] as const).map(category=><p key={category}>{category}: {bankCloseMoney(result.totals[category].toString())}</p>)}<div className="table-wrap"><table><caption>Remaining source balances</caption><thead><tr><th>Reference</th><th>Category</th><th>Opening</th><th>Applied</th><th>Collected or refunded</th><th>Remaining</th><th>Due date</th></tr></thead><tbody>{result.rows.map(row=><tr key={row.id}><td>{row.reference}</td><td>{row.category}</td><td>{bankCloseMoney(row.opening)}</td><td>{bankCloseMoney(row.applied)}</td><td>{bankCloseMoney(row.external)}</td><td>{bankCloseMoney(row.remaining)}</td><td>{row.due??'—'}</td></tr>)}</tbody></table></div><div className="table-wrap"><table><caption>Migrated balance activity</caption><thead><tr><th>Date</th><th>Activity</th><th>Amount</th><th>Reason</th><th>Journal</th><th>Correction</th></tr></thead><tbody>{result.activity.map(event=><tr key={event.id}><td>{event.date}</td><td>{event.kind.replaceAll('_',' ')}</td><td>{bankCloseMoney(event.amount)}</td><td>{event.reason}</td><td>{event.journal}</td><td>{!event.original&&!result.activity.some(other=>other.original===event.id)&&<button type="button" disabled={busy||correctionLocked||actionLocked||invoiceLocked} onClick={()=>setCorrection(event)}>Correct activity</button>}</td></tr>)}</tbody></table></div>{result.activity.length===0&&<p>No activity through this date.</p>}</>}<fieldset disabled={busy||correctionLocked||invoiceLocked}><FinancialOpeningAction scope={scope} reservation={reservation} rows={result?.rows??[]} onLocked={setActionLocked} onCompleted={()=>void load()}/></fieldset><fieldset disabled={busy||actionLocked||invoiceLocked}><FinancialOpeningCorrection scope={scope} reservation={reservation} target={correction} onLocked={setCorrectionLocked} onCompleted={()=>{setCorrection(null);void load()}}/></fieldset><fieldset disabled={busy||actionLocked||correctionLocked}><FinancialInvoiceApplication scope={scope} reservation={reservation} rows={result?.rows??[]} onLocked={setInvoiceLocked} onCompleted={()=>void load()}/></fieldset></section>;
}
